/// The slider step a click at fraction `f` (0 left .. 1 right) of the track picks.
pub fn slider_step(f: f32, steps: usize) -> usize {
    if steps <= 1 {
        return 0;
    }
    ((f.clamp(0.0, 1.0) * (steps - 1) as f32).round() as usize).min(steps - 1)
}
